 const server=createServer(async(req,res)=>{if(req.headers.authorization!==`Bearer ${state.secret}`){res.writeHead(401);res.end();return;}const parts=[];for await(const part of req)parts.push(part);const rpc=JSON.parse(Buffer.concat(parts).toString());let result:any;if(rpc.method==='tools/list')result={tools};else{const {name,arguments:args}=rpc.params;state.calls.push({name,args});if(name==='results'&&state.missingResults){res.destroy();return;}let raw:any;if(name==='lease_acquire')raw={ok:true,lease_id:'lease_fixture',token:1,expires_in_s:120};else if(name==='lease_release'){state.releases++;raw={ok:true,released:true};}else if(name==='lease_heartbeat')raw={ok:true,expires_in_s:120};else if(name==='submit'){const bytes=Buffer.from(args.xlsx_b64,'base64'),book=JSON.parse(bytes.toString());state.submissions++;state.byteSha=createHash('sha256').update(bytes).digest('hex');raw={ok:true,task_id:state.remoteId,sha256:state.badSubmitSha?'0'.repeat(64):state.byteSha,case_ids:book.cases.map((item:any)=>item.autoid)};}else if(name==='status')raw=state.refuseStatus?{ok:false,stage:'validation',dispatched:false,reason:'Synthetic status refusal'}:{ok:true,task_id:state.remoteId,state:'done',rc:1};else raw=state.refuseResults?{ok:false,stage:'validation',dispatched:false,reason:'Synthetic results refusal'}:{ok:true,task_id:state.remoteId,channel:state.queryError?'query_error':'ready',rc:1,xlsx_sha256:state.badResultsSha?'0'.repeat(64):state.byteSha,cases:[{case_id:'301',result:'fail'},{case_id:'302',result:'pass'}]};result={structuredContent:raw,isError:raw.ok===false,content:[{type:'text',text:JSON.stringify(raw)}]};}res.setHeader('content-type','application/json');res.end(JSON.stringify({jsonrpc:'2.0',id:rpc.id,result}));});await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));t.after(async()=>{server.closeAllConnections();await new Promise<void>(resolve=>server.close(()=>resolve()));});
 const h=await setup(t),profile={endpoint:`http://127.0.0.1:${(server.address() as any).port}/mcp`,pollMs:25};await writeFile(h.scratch+'/stage-profile.json',JSON.stringify({profiles:{fixture:profile}}));h.env.CIRCLE_HUB_EXECUTION_GATEWAYS=h.scratch+'/stage-profile.json';await h.stop();await h.startServer();
