 const candidate=()=>{const observed=find('submit'),raw=observed.facts.result,unavailable=observed.facts.interpretationStatus==='failed';return {cases:unavailable?[]:raw.cases??[],channel:unavailable?'unavailable':raw.channel??'unavailable',rc:raw.rc??null,unmapped:unavailable?observed.facts.unmapped:raw.channel==='ready'?[]:[{reason:'result_channel_incomplete'}],...(unavailable?{error:observed.facts.error}:{})};};
